/**
 * The owner's numeric membership level, derived on read: it starts at 1, gains 1 when an email
 * is present, gains 1 when {@link #namesakeCount} is 0, and is capped at 3 by these pre-tenure
 * factors. Level 4 is reserved for tenure: it is reached only when the pre-tenure factors are
 * maxed and the owner's tenure (whole days from {@link #registrationDate} to today) exceeds 365.
 * Because a newly created owner has zero tenure, a new owner never exceeds level 3.
 */
@Transient
public Integer getMembershipLevel() {
    return membershipLevel(this.email, this.namesakeCount, this.registrationDate);
}

/** The numeric membership level (1-4) derived from the given factors: it starts at 1, gains 1
 *  when {@code email} is present, gains 1 when {@code namesakeCount} is 0, and is capped at 3 by
 *  these pre-tenure factors. Level 4 is reserved for tenure: it is reached only when the
 *  pre-tenure factors are maxed and tenure (whole days from {@code registrationDate} to today)
 *  exceeds 365. */
private static int membershipLevel(String email, Integer namesakeCount, LocalDate registrationDate) {
    int level = 1;
    if (email != null && !email.isBlank()) {
        level++;
    }
    if (namesakeCount != null && namesakeCount == 0) {
        level++;
    }
    level = Math.min(level, 3);
    if (registrationDate != null
            && java.time.temporal.ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > 365) {
        level++;
    }
    return Math.min(level, 4);
}

/**
 * The owner's preferred contact channel, derived on read: {@code "EMAIL"} when an email is
 * present, otherwise {@code "PHONE"}.
 */
@Transient
public String getContactPreference() {
    return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
}

/**
 * The owner's age band, derived on read from the {@link #birthDate} relative to the
 * {@link #registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} from 18 to 64, and
 * {@code "SENIOR"} at 65 or over. Returns {@code null} when no birth date (or no registration
 * date to measure against) is available.
 */
@Transient
public String getAgeBand() {
    if (this.birthDate == null || this.registrationDate == null) {
        return null;
    }
    int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
    if (age < 18) {
        return "MINOR";
    }
    if (age < 65) {
        return "ADULT";
    }
    return "SENIOR";
}

